// Thin typed client for the FastAPI backend. The contract lives in backend/openapi.json
// (generated by FastAPI); keep these types in step with backend/app/schemas.py.

export const API_URL = (import.meta.env.VITE_API_URL as string | undefined)?.replace(/\/$/, '') ?? '';
export const isBackendConfigured = () => API_URL.length > 0;

const TOKEN_KEY = 'lr.token';
const EMAIL_KEY = 'lr.email';

export const auth = {
  get token() { try { return localStorage.getItem(TOKEN_KEY); } catch { return null; } },
  get email() { try { return localStorage.getItem(EMAIL_KEY); } catch { return null; } },
  save(token: string, email: string) {
    try { localStorage.setItem(TOKEN_KEY, token); localStorage.setItem(EMAIL_KEY, email); } catch { /* private mode */ }
  },
  clear() { try { localStorage.removeItem(TOKEN_KEY); localStorage.removeItem(EMAIL_KEY); } catch { /* ignore */ } },
};

export class ApiError extends Error {
  constructor(public status: number, message: string) { super(message); }
}

export async function request<T>(path: string, init: RequestInit = {}, timeoutMs = 15000): Promise<T> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  const headers = new Headers(init.headers);
  if (init.body && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
  const token = auth.token;
  if (token) headers.set('Authorization', `Bearer ${token}`);
  try {
    const res = await fetch(`${API_URL}${path}`, { ...init, headers, signal: ctrl.signal });
    if (!res.ok) {
      let detail = res.statusText;
      try { const j = await res.json(); detail = typeof j.detail === 'string' ? j.detail : JSON.stringify(j.detail); } catch { /* not json */ }
      if (res.status === 401) auth.clear();
      throw new ApiError(res.status, detail);
    }
    return (res.status === 204 ? undefined : await res.json()) as T;
  } finally {
    clearTimeout(timer);
  }
}

export interface TokenResponse { access_token: string; token_type: 'bearer' }

export async function login(email: string, password: string, mode: 'login' | 'register') {
  const r = await request<TokenResponse>(`/api/v1/auth/${mode}`, { method: 'POST', body: JSON.stringify({ email, password }) });
  auth.save(r.access_token, email);
  return r;
}

export async function translate(text: string, sourceLanguage: string, targetLanguage = 'en'): Promise<string> {
  const q = new URLSearchParams({ q: text, sl: sourceLanguage, tl: targetLanguage });
  const r = await request<{ text: string }>(`/api/v1/translate?${q}`);
  return r.text;
}
